  void HandleBoardInput(){if(Busy||modal!=""||puzzle.Remaining==0)return;var e=Event.current;Vector2 v=e.mousePosition;Rect board=new Rect(30,boardY,cellSize*5,cellSize*5);if(e.type==EventType.MouseDown&&e.button==0&&board.Contains(v)){int x=(int)((v.x-30)/cellSize),y=(int)((v.y-boardY)/cellSize);int a=Array.FindIndex(puzzle.positions,p=>p.x==x&&p.y==y);if(a>=0){selected=a;dragging=true;dragStart=v;dragSteps=0;showHelp=false;sound.Play(0);}else if(selected>=0){var p=puzzle.positions[selected];int xx=x-p.x,yy=y-p.y;if(xx==0||yy==0)Commit(selected,Math.Sign(xx),Math.Sign(yy),Math.Abs(xx)+Math.Abs(yy));}e.Use();}
   if(dragging&&(e.type==EventType.MouseDrag||e.type==EventType.MouseUp)){Vector2 delta=v-dragStart;dragDX=Mathf.Abs(delta.x)>Mathf.Abs(delta.y)?(int)Mathf.Sign(delta.x):0;dragDY=dragDX==0?(int)Mathf.Sign(delta.y):0;dragSteps=Mathf.RoundToInt(Mathf.Max(Mathf.Abs(delta.x),Mathf.Abs(delta.y))/cellSize);if(e.type==EventType.MouseUp){dragging=false;if(board.Contains(v)&&dragSteps>0)Commit(selected,dragDX,dragDY,dragSteps);else if(!board.Contains(v)){selected=-1;notice="移動を取り消しました。";}}e.Use();}}
  void Reward(){var l=book.levels[levelIndex];int id=l.rewards[rewardIndex];Box(new Rect(0,0,540,H),new Color(ink.r,ink.g,ink.b,.56f));T("FIELD "+l.id+"   COMPLETE",new Rect(25,42,490,33),19,gold,TextAnchor.MiddleCenter);T(firstClear?"新しい足音が、仲間に。":"また会えたね。",new Rect(28,88,484,55),31,paper,TextAnchor.MiddleCenter,true);float cy=H*.44f;for(int n=0;n<12;n++){float angle=n*Mathf.PI/6+Time.unscaledTime*.03f;Line(new Vector2(270+Mathf.Cos(angle)*155,cy+Mathf.Sin(angle)*155),new Vector2(270+Mathf.Cos(angle)*175,cy+Mathf.Sin(angle)*175),gold,2);}Animal(id,new Rect(80,cy-190,380,350));T(catalog.animals[id].name,new Rect(30,cy+180,480,55),38,paper,TextAnchor.MiddleCenter,true);T(catalog.animals[id].species+" / No. "+(id+1).ToString("00"),new Rect(30,cy+238,480,30),17,gold,TextAnchor.MiddleCenter);T(firstClear?"動物図鑑に登録しました":"登録済 / 仲間はそのまま残ります",new Rect(30,H-197,480,33),19,paper,TextAnchor.MiddleCenter);T(puzzle.moves+"手  /  ベスト "+PlayerPrefs.GetInt(SaveKey+".best"+levelIndex)+"手",new Rect(30,H-153,480,27),16,gold,TextAnchor.MiddleCenter);if(Button(rewardIndex<l.rewards.Length-1?"もうひとつの足音　→":"つづきを読む　→",new Rect(62,H-102,416,62),true)){if(rewardIndex<l.rewards.Length-1){rewardIndex++;entered=Time.unscaledTime;sound.Play(4);}else Story(true);}}
