   float y=gridTop+gridH+12;T(Has(card)?catalog.animals[card].name:"まだ見ぬ足音",new Rect(28,y,484,44),28,paper);T(Has(card)?catalog.animals[card].lore:"調査を進めると、この動物の記録が開きます。",new Rect(28,y+53,484,73),20,paper);if(Button("観測室に招く",new Rect(28,y+137,484,55),true,Has(card))){room[roomSlot]=card;Save();Change(Page.Room);}Nav();}
  void Room(){float ground=H*.69f;for(int i=0;i<3;i++){var r=new Rect(12+i*172,ground-200,172,213);if(room[i]>=0&&Has(room[i])){Animal(room[i],new Rect(r.x,r.y+Mathf.Sin(Time.unscaledTime*1.4f+i)*3,r.width,r.height));if(!photo)T(catalog.animals[room[i]].name,new Rect(r.x,r.yMax+9,r.width,30),18,ink,TextAnchor.MiddleCenter);}if(!photo&&room[i]<0){Border(new Rect(r.x+14,r.y+82,r.width-28,120),new Color(ink.r,ink.g,ink.b,.35f),1);T("＋",new Rect(r.x,r.y+95,r.width,65),36,ink,TextAnchor.MiddleCenter);}if(!photo&&Hit(new Rect(r.x,r.y,r.width,r.height+55))){roomSlot=i;Change(Page.Codex);}}
   if(photo){T("ANIMAL ARCHIVE",new Rect(25,H-63,490,32),19,ink,TextAnchor.MiddleCenter);if(Hit(new Rect(0,0,540,H)))photo=false;return;}Heading("MY OBSERVATORY","今日も、ここにいる。");T(Count(owned)==0?"最初の調査で仲間がやってきます。":"動物や空いた場所をタップして、仲間を招く。",new Rect(28,140,480,65),19,ink);if(Button("写真モード",new Rect(26,H-243,234,54),true)){photo=true;}if(Button(sound.Muted?"音：OFF":"音：ON",new Rect(280,H-243,234,54)))sound.Toggle();if(Button("調査記録を読む",new Rect(26,H-177,314,54),false,completed>0)){Change(Page.Records);}if(Button("設定",new Rect(360,H-177,154,54)))modal="settings";Nav();}
