  void Modal(){Box(new Rect(0,0,540,H),new Color(0,0,0,.75f));Box(new Rect(24,H/2-154,492,308),paper);string action=modal;T(action=="retry"?"配置を最初に戻しますか？":action=="map"?"地図へ戻りますか？":action=="reset"?"すべての調査記録を消しますか？":"観測室の設定",new Rect(46,H/2-122,450,70),26,ink,TextAnchor.MiddleCenter);T(action=="settings"?"音量は端末でも調整できます。":"途中の配置は保存されません。",new Rect(46,H/2-35,450,50),18,ink,TextAnchor.MiddleCenter);modal="";bool yes=Button(action=="settings"?"記録を消す":"はい",new Rect(48,H/2+62,210,62),true);bool no=Button("戻る",new Rect(282,H/2+62,210,62));modal=action;if(no)modal="";if(yes){modal="";if(action=="retry")StartPuzzle(levelIndex);if(action=="map")Change(Page.Map);if(action=="settings")modal="reset";if(action=="reset"){completed=owned=0;room=new[]{-1,-1,-1};PlayerPrefs.DeleteKey(SaveKey+".intro");for(int i=0;i<9;i++)PlayerPrefs.DeleteKey(SaveKey+".best"+i);Save();Change(Page.Title);}}}
